import{_ as o}from"./chunks/dashboard.dWD4oxS0.js";import{_ as r,C as n,o as e,c as s,a2 as l,b as i,w as a,a as c,E as g,a3 as h}from"./chunks/framework.BODD28Fk.js";const A=JSON.parse('{"title":"대시보드 (Dashboard) 사용 매뉴얼","description":"","frontmatter":{},"headers":[],"relativePath":"intro/dashboard.md","filePath":"intro/dashboard.md","lastUpdated":1793459412000}'),f={name:"intro/dashboard.md"};function x(y,t,u,E,m,b){const d=n("Mermaid");return e(),s("div",null,[t[1]||(t[1]=l('<h1 id="대시보드-dashboard-사용-매뉴얼" tabindex="-1">대시보드 (Dashboard) 사용 매뉴얼 <a class="header-anchor" href="#대시보드-dashboard-사용-매뉴얼" aria-label="Permalink to &quot;대시보드 (Dashboard) 사용 매뉴얼&quot;">​</a></h1><blockquote><p><strong>IBS 대시보드</strong>는 프로젝트 진행 상황, 분양 및 계약 지표, 자금 흐름, 그리고 개인의 업무/회의 현황까지 시스템 내의 핵심 데이터를 한눈에 모니터링할 수 있는 <strong>개인 맞춤형 지능형 포털</strong>입니다.</p></blockquote><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+o+'" alt="IBS 메인 대시보드 화면"></p></div><h2 id="_1-30초-만에-끝내는-대시보드-조작법" tabindex="-1">1. 30초 만에 끝내는 대시보드 조작법 <a class="header-anchor" href="#_1-30초-만에-끝내는-대시보드-조작법" aria-label="Permalink to &quot;1. 30초 만에 끝내는 대시보드 조작법&quot;">​</a></h2><p>대시보드는 레고 블록처럼 원하는 위젯을 배치하고 크기를 바꿀 수 있습니다.</p>',5)),(e(),i(h,null,{default:a(()=>[g(d,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E2%9A%99%EF%B8%8F%20%5B%EC%9C%84%EC%A0%AF%20%EC%84%A4%EC%A0%95%5D%20%ED%81%B4%EB%A6%AD%3Cbr%3E(%EC%9A%B0%EC%B8%A1%20%EC%84%9C%EB%9E%8D%20%EC%97%B4%EA%B8%B0)%22%5D%20--%3E%20B%5B%22%F0%9F%8E%9A%EF%B8%8F%20%EC%9B%90%ED%95%98%EB%8A%94%20%EC%9C%84%EC%A0%AF%20ON%2FOFF%3Cbr%3E(%EC%8B%A4%EC%8B%9C%EA%B0%84%20%EC%B6%94%EA%B0%80%2F%EC%88%A8%EA%B9%80)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%96%B1%EF%B8%8F%20%EB%A7%88%EC%9A%B0%EC%8A%A4%20%EB%93%9C%EB%9E%98%EA%B7%B8%3Cbr%3E(%EC%9C%84%EC%B9%98%20%EC%9D%B4%EB%8F%99%20%26%20%ED%81%AC%EA%B8%B0%20%EC%A1%B0%EC%A0%88)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E2%98%81%EF%B8%8F%20%EA%B3%84%EC%A0%95%20%EC%9E%90%EB%8F%99%20%EC%A0%80%EC%9E%A5%3Cbr%3E(%EB%AA%A8%EB%B0%94%EC%9D%BC%2F%ED%83%80%20PC%20%EC%9E%90%EB%8F%99%20%EB%8F%99%EA%B8%B0%ED%99%94)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[c(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h3 id="💡-위젯-추가-및-숨김-widget-drawer" tabindex="-1">💡 위젯 추가 및 숨김 (Widget Drawer) <a class="header-anchor" href="#💡-위젯-추가-및-숨김-widget-drawer" aria-label="Permalink to &quot;💡 위젯 추가 및 숨김 (Widget Drawer)&quot;">​</a></h3><ul><li>화면 우측 상단의 <strong>[위젯 설정]</strong> 버튼을 클릭하면 우측 서랍(Drawer) 패널이 열립니다.</li><li>필요한 위젯의 토글 스위치를 켜면 즉시 대시보드 빈 공간에 배치되며, 끄면 화면에서 숨겨집니다.</li><li>배치가 꼬였거나 초기 구성으로 되돌리고 싶다면 패널 하단의 **[기본값으로 초기화]**를 누르면 됩니다.</li></ul><h3 id="🧩-위젯-위치-이동-및-크기-조절-drag-resize" tabindex="-1">🧩 위젯 위치 이동 및 크기 조절 (Drag &amp; Resize) <a class="header-anchor" href="#🧩-위젯-위치-이동-및-크기-조절-drag-resize" aria-label="Permalink to &quot;🧩 위젯 위치 이동 및 크기 조절 (Drag &amp; Resize)&quot;">​</a></h3><ul><li><strong>위치 이동 (Drag)</strong>: 위젯 상단의 타이틀 바를 마우스로 잡고 끌면 원하는 위치로 바둑판 격자에 맞춰 매끄럽게 재배치됩니다.</li><li><strong>크기 조절 (Resize)</strong>: 위젯 우측 하단 모서리를 잡고 늘리거나 줄여 가로 폭과 세로 높이를 자유롭게 조정할 수 있습니다.</li></ul><h3 id="☁️-자동-클라우드-동기화-auto-cloud-sync" tabindex="-1">☁️ 자동 클라우드 동기화 (Auto Cloud Sync) <a class="header-anchor" href="#☁️-자동-클라우드-동기화-auto-cloud-sync" aria-label="Permalink to &quot;☁️ 자동 클라우드 동기화 (Auto Cloud Sync)&quot;">​</a></h3><ul><li>설정한 위젯의 위치와 크기는 사용자의 계정에 실시간 자동 저장됩니다.</li><li>회사 PC, 집 노트북, 태블릿, 모바일 어디서 로그인하든 <strong>내가 정성껏 꾸민 대시보드 레이아웃이 그대로 유지</strong>됩니다.</li></ul><h2 id="_2-⭐️-신규-임직원-추천-핵심-위젯-top-5" tabindex="-1">2. ⭐️ 신규 임직원 추천 핵심 위젯 TOP 5 <a class="header-anchor" href="#_2-⭐️-신규-임직원-추천-핵심-위젯-top-5" aria-label="Permalink to &quot;2. ⭐️ 신규 임직원 추천 핵심 위젯 TOP 5&quot;">​</a></h2><p>처음 시작하는 임직원에게 가장 권장하는 5가지 필수 위젯입니다.</p><ol><li><strong>내 업무 (<code>my-issue</code>)</strong>: <ul><li>나에게 담당자로 배정된 진행 중인 업무 목록과 마감일, 진척률을 확인하고 클릭하여 바로 처리할 수 있습니다.</li></ul></li><li><strong>전자결재 현황 (<code>approval-status</code>)</strong>: <ul><li>내가 기안한 품의서의 승인 진행 상황과, 내가 결재해야 할 대기 문서를 한눈에 파악합니다.</li></ul></li><li><strong>회의록 (<code>meeting-minutes</code>)</strong>: <ul><li>최근 참석한 회의의 핵심 결정 사항과 나에게 할당된 후속 조치(Action Item)를 놓치지 않도록 요약해 줍니다.</li></ul></li><li><strong>공지 목록 (<code>notice-list</code>)</strong>: <ul><li>전사 및 담당 프로젝트의 주요 공지사항과 중요 알림을 실시간으로 확인합니다.</li></ul></li><li><strong>빠른 작업 (<code>quick-actions</code>)</strong>: <ul><li>자주 쓰는 주요 업무(<code>거래 등록</code>, <code>업무 등록</code>, <code>계약 등록</code>, <code>일정 보기</code>, <code>납부 내역</code> 등)를 메뉴를 찾아 헤맬 필요 없이 단축 버튼으로 즉시 실행합니다.</li></ul></li></ol><h2 id="_3-전체-위젯-목록-16종-상세-안내" tabindex="-1">3. 전체 위젯 목록 (16종 상세 안내) <a class="header-anchor" href="#_3-전체-위젯-목록-16종-상세-안내" aria-label="Permalink to &quot;3. 전체 위젯 목록 (16종 상세 안내)&quot;">​</a></h2><p>IBS는 업무 성격에 따라 총 16종의 다채로운 위젯을 지원합니다. (⭐️: 초기 기본 활성화 위젯)</p><h3 id="🎯-협업-및-개인-업무-관리-위젯" tabindex="-1">🎯 협업 및 개인 업무 관리 위젯 <a class="header-anchor" href="#🎯-협업-및-개인-업무-관리-위젯" aria-label="Permalink to &quot;🎯 협업 및 개인 업무 관리 위젯&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">위젯 이름</th><th style="text-align:left;">영문 ID</th><th style="text-align:center;">기본 크기</th><th style="text-align:left;">주요 기능 및 연관 매뉴얼</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>내 업무</strong> ⭐️</td><td style="text-align:left;"><code>my-issue</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">본인에게 할당된 진행 중인 작업 목록 및 진척률 확인 → <a href="/work-manage/issue.html">업무 관리</a></td></tr><tr><td style="text-align:left;"><strong>회의록</strong> ⭐️</td><td style="text-align:left;"><code>meeting-minutes</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">최근 회의의 아젠다, 결정 사항 및 액션아이템 요약 → <a href="/work-manage/meeting.html">회의록 관리</a></td></tr><tr><td style="text-align:left;"><strong>전자결재 현황</strong> ⭐️</td><td style="text-align:left;"><code>approval-status</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">기안 상신, 결재 대기, 진행 중 문서 및 최근 결재 이력 요약 → <a href="/approval/">전자결재</a></td></tr><tr><td style="text-align:left;"><strong>이슈 트래커</strong> ⭐️</td><td style="text-align:left;"><code>issue-tracker</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">전체 업무(이슈)의 유형별/상태별 진행 통계 차트 → <a href="/work-manage/roadmap.html">로드맵</a></td></tr><tr><td style="text-align:left;"><strong>캘린더</strong></td><td style="text-align:left;"><code>calendar</code></td><td style="text-align:center;">12 × 5</td><td style="text-align:left;">프로젝트 주요 마일스톤, 업무 마감일, 회의 일정 시각화 → <a href="/work-manage/calendar.html">캘린더</a></td></tr><tr><td style="text-align:left;"><strong>활동 피드</strong></td><td style="text-align:left;"><code>activity-feed</code></td><td style="text-align:center;">3 × 4</td><td style="text-align:left;">시스템 전반에서 발생한 실시간 변경 및 작업 로그 타임라인 → <a href="/work-manage/activity.html">실행내역</a></td></tr></tbody></table><h3 id="🏢-프로젝트-및-분양·수납·영업-위젯" tabindex="-1">🏢 프로젝트 및 분양·수납·영업 위젯 <a class="header-anchor" href="#🏢-프로젝트-및-분양·수납·영업-위젯" aria-label="Permalink to &quot;🏢 프로젝트 및 분양·수납·영업 위젯&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">위젯 이름</th><th style="text-align:left;">영문 ID</th><th style="text-align:center;">기본 크기</th><th style="text-align:left;">주요 기능 및 연관 매뉴얼</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>프로젝트 현황</strong></td><td style="text-align:left;"><code>project-status</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">참여 중인 프로젝트의 기본 정보, 사업 기간, 전체 진행 상태 요약 → <a href="/project/">프로젝트 등록</a></td></tr><tr><td style="text-align:left;"><strong>프로젝트별 분양 계약률</strong></td><td style="text-align:left;"><code>contract-status</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">프로젝트별 분양 완료율 및 계약 상태 요약 도넛 차트 → <a href="/contract/status.html">동호배치 현황</a></td></tr><tr><td style="text-align:left;"><strong>최근 등록 계약</strong></td><td style="text-align:left;"><code>contract-log</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">최근 체결된 분양 계약 및 입금 트랜잭션 실시간 목록 → <a href="/contract/">계약 관리</a></td></tr><tr><td style="text-align:left;"><strong>분양 대행 및 수수료 정산</strong></td><td style="text-align:left;"><code>sales-status</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">회차별 분양 수수료 정산 현황, 총 세후 실지급액, 영업팀 지급 진척도 → <a href="/sales/settlement.html">수수료 정산 관리</a></td></tr><tr><td style="text-align:left;"><strong>프로젝트별 수납 현황</strong></td><td style="text-align:left;"><code>financial-status</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">회차별 수납액, 미납액 및 분양 대금 자금 흐름 그래프 → <a href="/payment/status.html">수납 현황</a></td></tr><tr><td style="text-align:left;"><strong>최근 문서 목록</strong></td><td style="text-align:left;"><code>document-list</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">프로젝트 및 본사에서 최근 공유된 공식 문서 목록 → <a href="/document/">문서 관리</a></td></tr></tbody></table><h3 id="⚡-정보-포털-및-편의-위젯" tabindex="-1">⚡ 정보 포털 및 편의 위젯 <a class="header-anchor" href="#⚡-정보-포털-및-편의-위젯" aria-label="Permalink to &quot;⚡ 정보 포털 및 편의 위젯&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">위젯 이름</th><th style="text-align:left;">영문 ID</th><th style="text-align:center;">기본 크기</th><th style="text-align:left;">주요 기능 및 상세 안내</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>오늘의 한마디</strong> ⭐️</td><td style="text-align:left;"><code>wise-word</code></td><td style="text-align:center;">12 × 2</td><td style="text-align:left;">매일 아침 새로운 비즈니스 격언 및 동기부여 메시지 표출</td></tr><tr><td style="text-align:left;"><strong>공지 목록</strong> ⭐️</td><td style="text-align:left;"><code>notice-list</code></td><td style="text-align:center;">6 × 4</td><td style="text-align:left;">전사 및 프로젝트별 최신 공지사항 목록 → <a href="/work-manage/news.html">공지 관리</a></td></tr><tr><td style="text-align:left;"><strong>빠른 작업</strong></td><td style="text-align:left;"><code>quick-actions</code></td><td style="text-align:center;">3 × 4</td><td style="text-align:left;">거래등록, 업무등록, 계약등록 등 8대 단축 버튼 모음</td></tr><tr><td style="text-align:left;"><strong>메인 슬라이드</strong></td><td style="text-align:left;"><code>main-carousel</code></td><td style="text-align:center;">12 × 5</td><td style="text-align:left;">주요 사내 배너 및 비주얼 이미지 슬라이드 뷰어</td></tr></tbody></table><h2 id="_4-직무별-추천-위젯-배치-템플릿" tabindex="-1">4. 직무별 추천 위젯 배치 템플릿 <a class="header-anchor" href="#_4-직무별-추천-위젯-배치-템플릿" aria-label="Permalink to &quot;4. 직무별 추천 위젯 배치 템플릿&quot;">​</a></h2><p>어떤 위젯을 어떻게 배치해야 할지 고민된다면 다음 직무별 추천 구성을 참고해 보세요.</p><ul><li><strong>프로젝트 총괄 (PM / 사업관리자)</strong>: <ul><li><strong>상단</strong>: <code>프로젝트 현황</code>, <code>전자결재 현황</code>, <code>이슈 트래커</code></li><li><strong>중단</strong>: <code>캘린더</code>, <code>회의록</code>, <code>활동 피드</code></li><li><strong>하단</strong>: <code>공지 목록</code>, <code>최근 문서 목록</code></li></ul></li><li><strong>영업 / 분양 / 수납 담당자</strong>: <ul><li><strong>상단</strong>: <code>프로젝트별 분양 계약률</code>, <code>분양 대행 및 수수료 정산</code>, <code>프로젝트별 수납 현황</code></li><li><strong>중단</strong>: <code>최근 등록 계약</code>, <code>내 업무</code>, <code>빠른 작업</code></li><li><strong>하단</strong>: <code>공지 목록</code>, <code>캘린더</code></li></ul></li><li><strong>일반 실무자 / 신규 입사자</strong>: <ul><li><strong>상단</strong>: <code>오늘의 한마디</code>, <code>내 업무</code>, <code>전자결재 현황</code></li><li><strong>중단</strong>: <code>회의록</code>, <code>캘린더</code>, <code>공지 목록</code></li><li><strong>하단</strong>: <code>빠른 작업</code>, <code>활동 피드</code></li></ul></li></ul>',20))])}const p=r(f,[["render",x]]);export{A as __pageData,p as default};
